{
  "implementation": "from collections import defaultdict

def solve(case):
    nodes = {n['id']: n for n in case['nodes']}
    children = defaultdict(list)
    root_id = None
    for n in case['nodes']:
        pid = n.get('parent')
        if pid is None:
            root_id = n['id']
        else:
            children[pid].append(n['id'])
    required = set(case['required_symbols'])
    retained = set(nodes.keys())
    removed_order = []
    sorted_ids = sorted(nodes.keys(), key=lambda nid: (-nodes[nid]['depth'], nid))
    for nid in sorted_ids:
        if nid not in retained:
            continue
        node = nodes[nid]
        if nid == root_id:
            continue
        if not node['removable']:
            continue
        if node['symbol'] in required:
            continue
        if any(child in retained for child in children[nid]):
            continue
        # compute subtree to remove (all retained descendants)
        to_remove = set()
        stack = [nid]
        while stack:
            cur = stack.pop()
            if cur in retained:
                to_remove.add(cur)
                stack.extend(children[cur])
        # check if all required symbols remain
        remaining_symbols = {nodes[r]['symbol'] for r in retained if r not in to_remove}
        if required.issubset(remaining_symbols):
            retained -= to_remove
            removed_order.append(nid)
    retained_sorted = sorted(retained)
    return {
        'retained_node_ids': retained_sorted,
        'removed_node_ids': removed_order
    }"
}
